import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"易传灯卷二","description":"易传灯 - 易传灯卷二","frontmatter":{"title":"易传灯卷二","description":"易传灯 - 易传灯卷二"},"headers":[],"relativePath":"zh/classics/yichuandeng/003.md","filePath":"zh/classics/yichuandeng/003.md"}'),n={name:"zh/classics/yichuandeng/003.md"};function c(r,p,i,_,o,d){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="易传灯卷二" tabindex="-1">易传灯卷二 <a class="header-anchor" href="#易传灯卷二" aria-label="Permalink to “易传灯卷二”">​</a></h1><p>钦定四库全书</p><p>宋徐氏撰坎上八卦 比需屯井既济蹇节</p><p>坎， 坎上坤下，众阴推戴，一阳处九五之位，日「比」。坎九五刚中在上，众阴下戴，无一人敢后者，故为「比」。比本乎坤，为易之门，行乎震、离、兑、乾之上为屯。既济、节、需四卦皆坎在上而阳进之卦，故屯者，坎上震下，其上之坎六四，上六辅九五，膏泽不流，为阴所害，下有震初九，居正得民，宜建为侯。若既济者，坎上离下，下离攻坎，三年克之为惫也。坎上兑下，兑二阳攻坎苦节，故曰「节」。坎上乾下，乾三阳需待以攻坎，六四「需血出穴」，故曰「需」。坎二小人得君于上，为下阳所攻，至需极矣。自需转而行巽、坎、艮，为井、坎、蹇之三卦，坎处阳之卦也。故井者，坎上巽下，言以井蓄水不汲用为废井，故繇辞「无丧无得，往来井井，汔至未繘井，未有功」。巽下二阳皆无与行恻，殆如东汉党锢之祸，不见用于君，此坎处君子，像旧井之不用也。若坎上坎下曰「习坎」，重险也。上坎上六失道，下坎初六失道，坎之为患，九二、九五皆被患者。九二坎有险，九五坎不盈，其为小人患明矣。若蹇者，坎上艮下，上坎九五爻为大蹇之文，坎为君患，虽得朋来，而未能免咎也。下体之艮，皆见险能止以为知，故九三往蹇来反，为内所喜，故曰「蹇」也。坎体二小人夹辅阳君于上，乱政害国，谗毁君子。易以井、坎、蹇卦序之，学者可不考哉！坎下八卦 讼涣困坎未济习 蒙解师 坎，陷也。一阳陷于二阴之中，二阴则为陷者也。其卦凡八，凡坎处于下体者，九二皆自上来陷，故圣人有「刚来得中」之文。讼九二之彖曰「刚来而得中」，故九二爻有「归逋」之象。困九二之彖曰「刚掩」，言九二见掩于阴而致困。九二能以酒食自养，故「朱绂方来」，言人君以臣服起用者也。兹九二所以为「贞大人吉」也。初六、六三为困于九二，故六三非所困而困，又处于刚上，所以致不祥之凶。解九二自震九四而来，因小人致解。九二直己自明，故曰「获三狐」，得中直之道。六三处非其分，负且乘，故致寇至。未济九二自五而来，能曳其轮而不行，所以贞吉。初六不知极而吝，六三未济征而凶，皆害二者也。讼、困、未济、解四卦，坎处于乾、兑、离、震之下，其九二皆自上来陷者也。若坎处于巽、坎、艮、坤之下者，为涣、坎、蒙、师，与前一义也。然坤上坎下为师，五阴用一阳帅师，则师九二非由上来陷者也。涣九二彖言「刚来不穷」，盖六四本六二也，六二上夺九四之位，故九四下为九二，有「涣奔其机」之文，言处于二，得所安也。初六之顺于九二、六三，则志在外，故曰「涣其躬」。若「习坎」之卦，上陷人君，而又下陷君子，故曰「重险」。九二在陷中，故曰「坎有险，求小得」。初六、六三为陷者也。初六失道既凶，六三来之坎坎，为下石之计，终无功也。小人之陷君子，虽能陷其身，而自小人视之，何功之有？清议所不容，必不自免其凶也。师九二在下得中，帅师之主。六三处九二之上，又欲为掌兵之权，权不出于一，所以致凶。蒙九二「以童蒙求我」，而为「包蒙纳妇，子之克家」者也。而六三行不顺，不有其躬，而依于九二，圣人所戒也。离上八卦 大有、噬、鼎、晋、嗑、未济、睽、旅、</p><p>离 离，中女，阴卦也。先天八卦，二阳夹辅一阴于中，权籍二阳也。离乘乾为「大有」，六五得位，上下应之，曰「大有」。自大有本乎乾，为易之门。行乎巽、坎、艮、坤之上，为鼎、未济、旅、晋四卦，皆离在上而阴进之卦，故离上巽下诸爻未有用也。离上坎下为未济，九二，男之穷，故曰「未济」。离上艮下为旅，离之九三，焚次丧仆，故曰「旅」。离上坤下为晋，晋下三阴，未遂其晋也。若离行乎震、离、兑之上，为噬嗑、离、睽三卦，离处阴之卦也。噬嗑之卦，离上震下，有位者皆用噬，而初、上则受罪者。离明在上，威动于下，用刑狱以儆于有位，非如乾命震而阴不为妄，此噬而后合，幸柔得中而上行也。离上离下为离上离，九四、上九辅六五以离，「王公致吉」。其下离，六二「黄离元吉」，故「畜牝牛吉」也。若睽者，离上兑下，离体二阳夹辅，阴君于上，多疑寡合，憎疾小人，故六三「舆曳」、「牛掣」为「睽」也。上下睽异，故九四、上九孤立于朝，为「小事吉」也。离下八卦 同人、家人、革、济、离、贲、丰、明夷。既</p><p>离处下体，六二皆自上来，丽乎两阳之间，两阳所以处此阴也，当随卦而言其义。同人之离，乃乾处阴于下之中而与之同，乾为九四、九三之间，乾兴大师克之，得与二遇也。革之下离，乃兑之处阴也，革六二任离体二阳之中，革服于阳，巳日乃革之，故「征吉」也。若离之离，乃止离之处阴也，六二依于二阳，柔丽中正，得所丽也，故曰「黄离元吉，畜牝牛吉」也。丰下之离，乃震处阴也。六二在离之中，为二阳所处。当丰之时，幽暗不明，不可以往，往得疑疾，「有孚发若，吉」。家人之离，巽处阴也。离体在下，初九、九三严于己以正家，六二柔顺，不能有立，无所遂，但在「中馈」则吉。既济之离，阴失位于上，今处于下，故六二「妇丧其茀，丧其为饰，无以为容，勿逐，七日得」，以中顺之道，得所丽也。贲下之离，君子小人往来为文，故六二在两阳间，得所丽为贲。明夷下离当阳刚诛阴之时，九三「南狩」，得其大首，而六二自上而下，顺于二阳，故用拯马壮吉，顺以则也。兹离在下八卦各有旨也。艮上八卦， 剥、畜、颐、蛊、贲、蒙、损、艮大</p><p>艮重坤上一阳乘五阴为剥者，阴剥阳也。阳非可剥也，五阴恃众而剥之，故艮乘坤曰剥。剥本乎坤，为易之门，故艮行。震、离、兑、乾之阳者，为颐。贲、损、大畜四卦，皆阳生于下之卦。若颐者，艮上震下，艮一阳上穷，震一阳下生，四阴中盛而阳微，故颐者，阴养阳之卦。故圣人有「观颐自求口实」之文。初九不能自求，为小人所诮，致有「观我朵颐」之凶。贲者，艮上离下，柔来文刚，刚上文柔，君子小人之相为贲也。损者，艮上兑下，损下益上，损三益上，损刚益柔，为损。大畜，艮上乾下，乾三阳为艮所畜，曰「大畜」。若艮处于巽、坎、艮之上者，为蛊、蒙、艮三卦为阳为阴，用也。艮上巽下，为蛊，刚上柔下，与之干蛊。艮上坎下为蒙，九二为「发蒙」也。艮上艮下为艮，下不求于上，故「不获其身」；上不求于下，故「不见其人」。兹为上下敌应，不相与也，所以为艮也。艮下八卦 遁、渐、咸、蹇、旅、艮、小过、谦。</p><p>艮者，止也。阳止于二阴之上，非阴止也。二阴长于下，一阳止于上，学者当究二阴何以为进身之计，一阳何以为处阴之计。而或者以为阳止阴，非也。故艮重于下者凡八卦，其六二皆有进志，九三皆有溺二之意。然究象辞，圣人每非三之与二也。遁六二用中顺之道，固执于阳，莫之能解，六二依阳以进也，九三系恋于二，故圣人以为畜臣妾则吉，而谓其不可大事也。咸六二之「咸其腓」，望阳之来感，而贵于居吉，则不失矣。然九三随人以为感，圣人以为吝道也。旅六二之「即次」，进得所安，而九三在旅为与下之道，圣人所以伤其「丧童仆」也。小过六二「遇其臣不及其君」，得所遇于九三矣。而九三以阴过盛而乃防之，故致「从或戕」之凶。四卦艮重于乾、兑离震之下者也。若艮处于巽、坎艮坤之下者，曰渐、蹇、艮、谦。渐之六二「鸿渐于磐」，言进得所安也。九三之「征」而不复，致二之「妇孕」而不育，而圣人谓三之「离群丑」也。蹇六二尽匪躬之节，而九三来反为内所喜，而圣人有「贞吉」与「无尤」之辞。艮六二不拯其随，未退听于九三，而九三之「艮其限」，自以止为道，不复顾于二也。谦六二之「鸣谦」，心中自得，而九三亦以谦自处，然其相得之情，观于「鸣谦」，义可知矣。兑上八卦 夬萃大过革困兑咸随 兑重乾上，一阴乘五阳为夬。夬，决柔也。一阴一阳之谓道，阴非可决也，五阳恃众而决之，故兑乘乾曰「夬」。夬本乎乾，为易之门，故兑行乎巽、坎、艮、坤之阴者为大过。困、咸、萃四卦皆阴生于下之卦。若大过者，兑上巽下，兑之一阴上穷，巽之一阴下生，为本末弱，阳盛于中而本末弱，为栋桡之象，故曰「大过」。若困者，兑上坎下，坎之九二乃上刚掩于二为困。困之九二自上而来，揜于二也。刚揜有言不信，初六、六三乃为困于九二者，九二以酒食自养，故能有庆。若咸者，兑上艮下为咸，柔上刚下，感应相与曰「咸」。萃者，兑上坤下坤，三阴下盛，言人民萃聚也。大过、咸、萃皆阴生长之卦。兑行于震、离，兑为随、革、兑三卦，皆处阴上之卦。兑上震下为随，初九乃刚来下柔，得众阴之随，故曰「随」。兑上离下为革，离之二阳处阴，而阴革服也。兑上兑下为兑，言阴说从也。兑重于震、离，兑之上为随、革、兑三卦，言阴之随而革且说也。自夬生大过、困、咸、萃皆阴生于下之卦，以至为随、革、兑，而阴随革且说。易序兑于后，言顺天应人，厥有旨矣。兑下八卦 履、孚兑、节、睽、损、归妹中临</p><p>兑者，说也。一阴处于二阳之上，处非其所，故求说乎阳，冀得所安也。故兑体重于八卦之下。六三多求说于阳，二阳在下，难乎其处此也。履六三履刚而处上，六三能说而应乾，故免咥人之凶，而论其才，则不足取也。兑六三则曰「来，兑」，来说于阳，所以凶。「临」之六三以二阳之长则甘临，亦求说于阳，故「无攸利」。归妹六三反归为娣，礼以从人，未当也。损六三当得友之时，无所损也。「节」六三当君子疑畏之际，不节而嗟，无所归咎，嗟为君子所诛也。睽时，上下不相和同之际，六三疑畏，欲行而舆曳，欲顺而牛掣，虽无初而有终，终则遇刚也。身处危疑，据刚之上，处非所安，故疑惧如此。若「中孚」则不然，疑其攻己，或鼓或罢，或泣或歌，始欲攻之，终安其所，盖其处位不当故也。</p><p>文王之重卦，必严于上下二体之辨。上为何卦，下为何卦，而后立之卦。观其卦象，系之繇辞，以明吉凶。其刚柔相推之变，先后反对之序，无不该于本卦二体之内，然后发挥于刚柔，而明其爻。非于本卦六爻之外，而即复、姤、临、遁、泰、否六卦为之母，以论外变也；非以互体动爻之外，取象而为辞也。如需后有讼，「需」，乾三阳在下，攻坎出穴之卦。讼，乾三阳在上，一阳归逋之卦。盖八卦成列，乾右有巽、坎、艮三卦，其「坎」者，乾之上阳来陷于二也。故讼卦有「刚来得中」之文，爻有「不克讼，归逋」之文。朱汉上不究八卦成列之图象在其中之语，乃因讼曰「刚来得中」，无妄曰「刚自外来而为主于内」。朱以讼者遁三之二，无妄者遁三之初九。言外者皆自外。朱谓初、二两爻视三则外矣。朱盖以复、姤、临、遁、泰、否六卦言变，而不知非易之变象也。愚未见内体三爻自分内外也。若无妄卦乾上震下，其初九有「刚自外来为主于内」之文。盖乾之重卦凡八卦，乾、姤、讼、遁、否、无妄、同人、履。皆乾在上所重之卦，其下体所乘讼、遁、无妄者，皆乘三男，其阳皆自上来而处于内者也。朱汉上不以乾重卦为无妄之所本，盖无妄自否来也。否，坤之三阴内乘乾，即命震以一阳为主于内，故震之一阳自乾外来，为内之主。由是阴畏震威，不为妄而邪恶屏息矣。兹天之命震为主，自乾而来，而非遁自三之初，为无妄之初九也。吁！重卦之上下二体，即有上下刚柔相推之象，本于八卦之成列，而后有八卦之相错。数往者以顺而数其往，知来者以逆而知其来，非可指复、姤、临、遁、泰、否六卦为之母，而妄为卦变之往来。后之学者，不能于每卦上下论相乘相感之理，而推圣人观象之旨，不得其要领，而于卦外言说，或言爻应，或言世变，或言互体，或言变体，自以为立论出于三圣所见之表。盖自汉以下，万人一律。吁，易道为异说所汨，可胜叹哉！宜王通氏谓「九师兴而易道微也」，宜王弼之有阴谪也。</p><p>易言「元亨利贞」凡七处，乾坤「元亨利贞」二处，彖谓之四德，圣人无所增损其义也。自「屯」而下，彖皆作「大亨」，以正释之，而于「利」之一字，不连本文也。然后知「元亨贞」者，卦中自有「元亨贞」之德，而文王于「贞」上断之以「利」于「贞」而已。此夫子所以不连「利」于「贞」为卦中之义也。屯曰「大亨贞」，随曰「大亨贞」，无妄曰「大亨以正」，临曰「大亨以正」，革曰「大亨以正」，皆不连「利」字者，乃知「利」者，文王之断辞所加也。今而后读「元亨」为一句，「利贞」为一句，庶得孔氏之意。</p><p>易有「安贞」、「艰贞」、「居贞」之辨，又有「女子贞」、「幽人贞」、「妇人贞」、「武人贞」、「牝马贞」之别。其「安」「居」与「艰」，皆以字义为「贞」也。其女子、幽人、妇人、武人等贞，皆以人物为象也。「贞」于「安」，如坤卦「安贞」，讼九四「安贞吉」。贞于「居」，如屯爻「利居贞」。贞于艰，如泰九五「艰贞无咎」，明夷「利艰贞」，如大畜九三。「利艰贞」，如噬嗑九四「利艰贞吉」。此皆以字义为「贞」也。其「女子贞」者，屯六二爻言「女子贞」。又「幽人贞」者，履九二爻；「利幽人贞」者，归妹九二之爻；「贞妇人吉」者，恒六五之爻。「贞大人吉」者，困之彖谓九二也。「贞丈人吉」者，师彖谓九二也。盖以字义为「贞」者，当详安居艰难之义。以人物为「贞」者，当详妇人、女子、幽人、丈人、武人之义。外有「利君子贞」、「大贞」、「小贞」，皆可详也。「贞」者，事事之干，能详究圣人立贞文多等之理，则知「利贞」、「贞吉」、「贞厉」、「贞吝」者，其义轻重，皆可沿而知之矣。</p><p>易爻以「血」为象，皆以有所伤为义，非以坎卦为血也。坤上六「其血玄黄」，言上六与阳战，两有所伤也。此岂坎卦哉？需六四「需于血」，言六四为三阳所攻，有所伤而去也。小畜六四言「血去」，以六四结知于君，免为三阳所害。涣上九言「血去」，以九阳明能远害全身，免为六四所害也。小畜与涣皆巽体，岂皆坎卦哉？诸解者以坎为血卦，见诸爻以血为象者，牵强附会，以坎为说。吁，亦诬矣。</p><p>易以十年、三年、三岁为爻象者，以爻之吉凶轻重为久近之数。然十年为数之至重也。如屯六二「女子贞，十年乃字」。言六二有乘刚之难，义不从寇，故久而后反常乃字也。复上六「迷复行师，自取其凶，十年不克征」。所以为凶之至重也。又如颐六三拂乱其颐养之道，贞久于拂，大悖于道，虽十年勿用，故皆以十年为象也。外以三年、三岁为象者，比之十年为凶之轻，而数至于三，亦罹罪之重也。如同人伏戎敌刚，知其义不可与大师为敌，故至三年不敢兴戎也。坎上六失事君之道，徽𬙊丛棘，凶至三岁不得免也。困初六坐受其困，致不明之灾，在下而为困于人，自罹其困，虽三岁不觌也。丰上六丰大其屋，蔀蔽于家，失道无助，虽三岁亦不觌也。兹易以三年言得凶之重也。外既济以「三年克鬼方」为惫，未济以「三年伐鬼方」为志行，随爻取象，各不同也。然易象以三数为重，「王三锡命」，示赏功之礼；「昼日三接」，示康侯之宠；「田获三品」，示得功之多；「三日不食」，示于行之义。易以三为贵，审矣。易象又以「七日」言者，复之「七日来复」，圣人以为天行，而子夏、胡安定、伊川苏氏诸解，皆以坤极六位，而反于坤之复，其数七日，凡历七爻，以一爻为一日，故云「七日」也。而震六二：「丧贝，勿逐，七日得。」既济六二：「妇丧其茀」，亦曰：「勿逐，七日得。」小象以七日得，为以中道也。圣人于复言天行，于既济言中道，则七日象数，易固有则也，奚容以私意臆度论？</p><p>文王作卦下辞，多以「利涉大川」为象，或言「不利涉大川」者，或以爻辞中亦言「利涉大川」者。盖圣人观卦象之难，如需下三阳，上诛坎险，其事至难。如大川之难涉，必勇往有为，则事遂，故以「利涉大川」为象。故需之彖曰：「利涉大川，往有功也。」又如蛊弊难拯，如大川之难涉，必勇往有为则事遂，故曰：「利涉大川，往有事也。」如讼之群刚，希冀非望，如涉川之难，非可勇往利涉，故曰：「不利涉大川，入于渊也。」若夫同人之「利涉大川」者，以九五与六二之同，多有难阻，乾兴大师克之，得与二遇，故彖言「同人于野，亨，利涉大川，乾行也」，乾用大师克相遇，故以「利涉大川」为象也。大畜利涉大川者，大畜君子当朝廷养贤之时，不家食致吉，虽勇往求君，有为亦所利也。九三爻言「利有攸往」，与上合志，即涉川应天之旨也。后益卦「利涉大川」，涣卦「利涉大川，中孚利涉大川」者，三卦皆巽体在上，六四有功，故三卦彖辞益言「木道乃行」，涣言「乘木有功」，中孚言「乘木舟虚」也。木即巽六四也。六四有功，故言木道乃行，乘木有功也。外爻辞谦初六谦谦卑以自牧，虽事之难，君子亦可勇往用涉也。颐上九：既由我颐养于天下，虽事如涉川之难，亦利涉也。若夫未济六三：「未济，征凶，利涉大川。」盖六三当未济而上征则凶，虽上征之难，亦可勇而有为而利涉也。故虽「未济征凶」，而利涉有为也。若夫颐六五：「拂经为颐，居贞则吉」，则不可涉川为难事，故言「不可涉大川」也。圣人以涉川为象，皆以卦爻事象之难者，立文取譬，有利有不利，其旨深矣。后之学者，当自考之。</p><p>蛊卦「先甲三日，后甲三日」，言前治后治也。未蛊之前，前可为大治矣。饬蛊之后，后尤为大治也。「先甲三日」，言承前治之统也。「后甲三日」，言垂后治之统也。故彖辞谓「终则有始，天行也」。前治已终矣，后治今始也。蛊所以为元亨而天下治也。巽卦「先庚三日」，言申天命未已也。旅君失国之先，天命已久矣。巽君中兴之后，天命方新也。先庚三日，天始命于国家者，其历数可谓长矣。后庚三日，天复命于国者，其历数尤为长也。故彖辞谓重巽以申命于三日之先，知天命之未改也。申其命于三日之后，知天命之尤长也。巽所以申命行事也。或者立为甲庚之图，则非矣。</p><p>周建子为正月，一阳生为复，二月丑为临，刚浸而长。三月三阳泰，四月四阳大壮，五月五阳而夬，六月乾，七月姤，一阴生，至八月遁，二阴浸长则阳遁，君子道消，故圣人于临言八月有凶，消不久也。后至否，三阴盛也；观，四阴盛也；剥，五阴盛也。至亥月坤，纯阴用事，阴之消阳至此极矣。然后至周建子为阳生之月，圣人于临言八月有凶，盖临二阳长之时，至八月当二阴长之卦，阴长则阳消，故至遁时八月有凶，圣人戒之于早也。吁，圣人立阳长卦名有六，曰复临泰大壮夬乾。又立阴长卦名有六，曰姤遁否观剥坤。盖托阴阳消长之序，为君子小人进退之候。当二阳之临，曷可不存二阴之遁于八月哉？圣人为君子虑者切矣。</p><p>卦以震、巽之长，坎、离之中，艮、兑之少，可为夫妇。而质之易爻不然。盖卦爻以上下二体所属刚柔阴阳为夫妇之象。如渐九三爻言：「夫征不复，妇孕不育。」盖「夫征」言九三也，「妇孕」言六二也。九三之「征不复」而离群丑，故六二之「妇孕不育」也。又渐九五爻言：「妇三岁不孕，终莫之胜，吉。」谓九五之君不庇于六四，故六四之「妇三岁不孕」也。又如蒙卦六三爻言：「勿用取女，见金夫，不有躬，无攸利。」言六三之阴下求九二，以九二为「金夫」，不有躬而相从，故小象以为「行不顺也」。「金夫」言刚夫也。前辈诸解作人之多金，六三说而从之，恐圣人取象之意，不如是之屑。如「金夫」、「金柅」，皆以刚取义也。又如大过卦诸爻言「老夫」「女妻」、「老妇」、「士夫」，有老少之别者，以大过卦刚过为象，故于爻有老少之辨也。九二爻言「老夫」者，言九二也。「女妻」者，言初六也。九二「老夫」得初六柔在下而阴生，是女妻也，故有老夫、「女妻」之象。九五、上六爻言「老妇」、「士夫」者，「士夫」言九五也，「老妇」言上六也。上六「老妇」得九五「士夫」为可丑也。兹夫妇取象，又以阴阳老少为象，学者又当详之。</p><p>易自中兴之后，国家亦多变故矣。圣人作巽后爻辞，言国家时变不一也。虽更历千万代，其应如响。盖天命所系，圣人岂隐于易哉？巽上之「丧其资斧」，言中兴之君，太阿倒持，优游不断之象也。兑五之「孚于剥」，言中兴之后，信谗佞，远忠直，而得位于上。如汉元帝信许氏，杀萧望之之类也。涣五之「涣王居」，盖后世东迁之象也。涣上之「血去远害」，盖秦时望夷宫中，唐宪、敬遇害之象也。遂致节九五「甘节，往有尚」，得位中之吉，如唐称国舅、国㸙，甘言免患之类也。传至屯蒙，屯九五位于小人之中，膏泽不流，蒙之童幼，顺巽幸免。至于需之兴戎，而小人出穴，小人窟穴甫除，而讼之群奸已睥睨于旁，巽后大变极矣。幸而师、比之真人勃兴，师之用众，比之推戴，明阳之建极未几。同人之应君，大有之柔位，明阴之建极，由巽而讼，历数可推。阴阳建极，而天命延长，不可测矣。</p><p>易之卦爻言无咎者多矣。圣人谓无咎者，善补过也。如睽初九「见恶人，无咎」，见恶人，以辟咎也。离初九「履错然，敬之，无咎」，履错之敬，以辟咎也。兹补过而免咎者也。有何咎、何其咎者，小畜初九「复自道，何其咎，吉」、随九四「有孚在道，以明，何咎」？睽六五「厥宗噬肤，往何咎」？兹其过，咎之必无者也。有义无咎者：复六三「频复」之厉，义无咎也；解初六刚柔之际，义无咎也；渐初六「小子」之厉，义无咎也；既济初九「曳其轮」，义无咎也。至大有初九则曰「无交害，匪咎，艰则无咎」。然有不可归咎于人者，如同人初九「出门同人」，又谁咎也；解六三自我致戎，又谁咎也；节六三不节之嗟，又谁咎也？然大过上六「过涉灭顶，凶，无咎」，过涉之凶，不可咎也，兹取凶之不可怨咎者也。有自取其咎者，如夬初九「往不胜为咎」，不胜而往，咎也。有「无大咎」者，如蛊九三「小有悔，无大咎」，姤九三「厉，无大咎」。有「终无咎」者，如习坎六四「纳约自牖，终无咎」，夬九三之象「君子夬夬，终无咎也」。易言「无咎」多端矣，非可一义为言也。虽均曰「无咎」，易爻变易以贡，神而明之，则存乎人焉。乾九三虽危而无咎，九四或疑而无咎，兹善补过而无咎，异乎前之无咎多等者矣。</p>',20)])])}const m=a(n,[["render",c]]);export{h as __pageData,m as default};
